// Shape of the open source notices generated by scripts/generate-oss-notices.mjs.

/**
 * Where a component comes from: an npm package (used to build or run the apps), a native iOS
 * component, a native Android component, or a native component in both.
 */
export type OssPlatform = 'npm' | 'ios' | 'android' | 'ios-android';

export interface OssNotice {
    /** Package, pod or Maven module (group:artifact) name. */
    name: string;
    version: string;
    platform: OssPlatform;
    /** Declared license (SPDX expression where the component gives one; UNKNOWN when it declares none). */
    license: string;
    /**
     * Index into OSS_LICENSE_TEXTS, or -1 when no license text is reproduced (the component ships no
     * license file; with `notice`, it ships only a third-party notices file).
     */
    text: number;
    /**
     * Present when the shipped library includes a non-empty third-party notices file
     * (third_party_licenses.txt) that is not reproduced here. It says nothing about where the
     * component's own license terms are; that license is the declared `license`.
     */
    notice?: 'bundled_not_reproduced';
}
